ANCHOR = {"it":"Gestisci le playlist","en":"Manage playlists","es":"Gestionar listas","fr":"Gérer les playlists",
          "de":"Playlists verwalten","pt":"Gerir listas","ro":"Gestionează playlisturile","tr":"Listeleri yönet"}
s = P.read_text()
if '"dev.title"' in s:
    raise SystemExit("already applied")
for lang, vals in T.items():
    assert len(vals) == len(KEYS), lang
    anchor = f'  "pl.banner.button": "{ANCHOR[lang]}",\n'
    assert s.count(anchor) == 1, lang
    block = "".join(f'  "dev.{k}": {json.dumps(v, ensure_ascii=False)},\n' for k, v in zip(KEYS, vals))
    s = s.replace(anchor, anchor + block)
P.write_text(s)
print("ok")
